<?php require_once '../includes/auth.php'; require_once '../includes/csrf.php'; require_once '../includes/functions.php'; $user=require_login(); verify_csrf(); $name=trim($_POST['customer_name']??'');$phone=trim($_POST['phone']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$date=$_POST['delivery_date']??'';$qty=filter_var($_POST['quantity']??0,FILTER_VALIDATE_INT);if(!$name||!$phone||!$email||!$date||$qty<1){flash('error','Completa todos los datos.');redirect('reserva.php');}$code='AV-'.strtoupper(bin2hex(random_bytes(5)));$stmt=db()->prepare('INSERT INTO reservas(code,user_id,customer_name,phone,email,delivery_date,quantity,notes) VALUES(?,?,?,?,?,?,?,?)');$stmt->execute([$code,$user['id'],$name,$phone,$email,$date,$qty,trim($_POST['notes']??'')]);flash('success','Reserva creada: '.$code);redirect('dashboard.php');
